import "server-only";

import { extractText, getDocumentProxy } from "unpdf";

import { MIN_TEXT_LENGTH, type OcrOutcome, type OcrProvider } from "./types";

/**
 * PDF text-layer extraction.
 *
 * Most supporting documents arrive as PDFs generated by a clinic or a school
 * system, which carry a real text layer. Reading it is exact, instant, free, and
 * needs no credentials — everything a cloud OCR call would need.
 *
 * A scanned PDF has no text layer. Rather than pretending, this provider reports
 * `unsupported` so the UI can tell the student to type the values instead.
 */
export const pdfTextProvider: OcrProvider = {
  name: "pdf-text",

  supports(mimeType) {
    return mimeType === "application/pdf";
  },

  async extract({ bytes }): Promise<OcrOutcome> {
    try {
      const document = await getDocumentProxy(new Uint8Array(bytes));
      const { text } = await extractText(document, { mergePages: true });
      const normalized = Array.isArray(text) ? text.join("\n") : text;
      const trimmed = normalized.trim();

      if (trimmed.length < MIN_TEXT_LENGTH) {
        return {
          status: "unsupported",
          provider: this.name,
          reason: "This PDF has no readable text layer (it looks scanned).",
        };
      }

      return { status: "succeeded", provider: this.name, text: trimmed };
    } catch {
      // A corrupt or encrypted PDF is a normal outcome, not a server error.
      return {
        status: "failed",
        provider: this.name,
        reason: "This PDF could not be read.",
      };
    }
  },
};
